pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    function testFuzz_property(address actor, bytes calldata data) public {
        vm.assume(actor != address(0));
        Succeeder s = new Succeeder();
        vm.prank(actor);
        bool ok;
        try c.forward(address(s), data) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract Succeeder {
    fallback() external payable {}
}
